// This file was generated by Prisma, and assumes you have installed the following:
// npm install --save-dev prisma dotenv
import "dotenv/config";
import { defineConfig } from "prisma/config";

// Vercel's Neon integration peut injecter la variable sous plusieurs noms
// selon la génération du connector (DATABASE_URL, POSTGRES_PRISMA_URL ou
// POSTGRES_URL). On fallback de l'un à l'autre pour que `prisma migrate
// deploy` fonctionne sans config supplémentaire dans Vercel.
const databaseUrl =
  process.env.DATABASE_URL ||
  process.env.POSTGRES_PRISMA_URL ||
  process.env.POSTGRES_URL ||
  process.env.POSTGRES_URL_NON_POOLING;

export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
  },
  datasource: {
    url: databaseUrl,
  },
});
